package com.example.starter.model;

/**
 * 粮仓状态：日常监测→异常告警→通风作业→效果复测→归档；两轮复测仍超标转人工处置。
 */
public enum SiloStatus {
    /** 日常监测 */
    MONITORING,
    /** 异常告警 */
    ALARMING,
    /** 通风作业 */
    VENTILATING,
    /** 效果复测 */
    RECHECKING,
    /** 两轮通风仍超标，转人工处置 */
    MANUAL_HANDLING,
    /** 已归档（终态），此后迟到温湿度数据只记迟到事件 */
    ARCHIVED
}

package com.example.starter.model;

/**
 * 风机状态；同一台风机同一时刻只服务一个仓。
 */
public enum FanStatus {
    /** 空闲 */
    IDLE,
    /** 已锁定到某个通风作业 */
    LOCKED
}

package com.example.starter.model;

/**
 * 通风目的：降温、降水、调质三类。
 */
public enum VentilationPurpose {
    /** 降温 */
    COOLING,
    /** 降水 */
    DEHUMIDIFYING,
    /** 调质 */
    CONDITIONING
}

package com.example.starter.model;

/**
 * 通风作业状态；归档为终态。
 */
public enum JobStatus {
    /** 执行中 */
    EXECUTING,
    /** 已完成（通风结束，待复测/归档） */
    COMPLETED,
    /** 已归档（终态） */
    ARCHIVED
}

package com.example.starter.model;

/**
 * 复测处置决策。
 */
public enum RecheckDecision {
    /** 梯度合格，待归档 */
    PASSED,
    /** 梯度仍超标且未满两轮，允许二次通风 */
    SECOND_VENTILATION,
    /** 两轮通风后梯度仍超标，转人工处置 */
    MANUAL_HANDLING
}

